import heapq


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, revision_first, discounted):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if revision_first:
            key = (event.get("revision", 0), position)
        else:
            key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = sorted({row["version"] for row in packages[name]
                           if row["version"] not in blocked.get(name, [])
                           and (name not in pins or row["version"] == pins[name])})
        options.append([-1] + versions)

    best_vector = None
    best_installation = None
    for vector in product(*options):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        if any(name not in installed or not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        rows = {}
        edges = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = next((r for r in packages[name] if r["version"] == version), None)
            if row is None:
                valid = False
                break
            rows[name] = row
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                edges[name].append(other)
                if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in installed:
                valid = False
                break
            reachable.add(name)
            pending.extend(edges[name])
        if not valid or reachable != set(installed):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges[name]):
                return False
            state[name] = 2
            return True

        if not all(visit(name) for name in installed):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = installed

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in available}) or k > len(available):
        return {"error": "impossible"}

    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(sum(job["start"] <= time < job["end"] for job in subset) > 2
               for time in (job["start"] for job in subset)):
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            departure = max(arrival, edge["open"])
            if departure >= edge["close"]:
                continue
            durations = [(edge["duration"], coupons)]
            if coupons:
                durations.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, remaining in durations:
                next_time = departure + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, remaining))
    return {"arrival": None}


